def countAllOnesSquares(matrix):
    n = len(matrix[0])
    prev = [0] * (n + 1)
    total = 0
    for row in matrix:
        cur = [0] * (n + 1)
        for c in range(n):
            if row[c] == 1:
                cur[c + 1] = 1 + min(prev[c], prev[c + 1], cur[c])
                total += cur[c + 1]
        prev = cur
    return total
